import{_ as i,o as a,c as e,a3 as r}from"./chunks/framework.CJlOecQn.js";const g=JSON.parse('{"title":"نحتاج مساعدتك","description":"معلومات يحتاجها القراء ولم نستطع تأكيدها من صفحة رسمية حتى الآن.","frontmatter":{"title":"نحتاج مساعدتك","description":"معلومات يحتاجها القراء ولم نستطع تأكيدها من صفحة رسمية حتى الآن."},"headers":[],"relativePath":"ar/help-wanted.md","filePath":"ar/help-wanted.md"}'),o={name:"ar/help-wanted.md"};function t(n,l,h,s,d,u){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="نحتاج-مساعدتك" tabindex="-1">نحتاج مساعدتك <a class="header-anchor" href="#نحتاج-مساعدتك" aria-label="Permalink to &quot;نحتاج مساعدتك&quot;">​</a></h1><p><strong>معلومات غير مؤكدة، ساعدنا فيها.</strong> لا شيء في هذه الصفحة يُعد نصيحة. هذه نواقص: معلومات يريدها القارئ وتركناها خارج الدليل لأننا لم نقرأها في صفحة رسمية.</p><p>إذا استطعت فتح الصفحة الرسمية، فأرسل <a href="https://github.com/Ifazawezk/living-in-qatar/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">تصحيحًا</a> مع الرابط. صورة إعلان في مركز خدمة أو لقطة شاشة من تطبيق تفيدنا كبداية، لكن الدليل يحتاج في النهاية إلى صفحة رسمية عامة يستشهد بها.</p><h2 id="الأكثر-إلحاحًا" tabindex="-1">الأكثر إلحاحًا <a class="header-anchor" href="#الأكثر-إلحاحًا" aria-label="Permalink to &quot;الأكثر إلحاحًا&quot;">​</a></h2><ul><li><strong>نص قانون العمل.</strong> تعتمد <a href="./guide/work-and-labour-rights">صفحة العمل</a> على كتيب صدر في ديسمبر 2021 عن اللجنة الوطنية لحقوق الإنسان، وعلى نسخة إنجليزية من القانون تعود إلى يناير 2006 لمبلغ مكافأة نهاية الخدمة، لأننا لم نستطع فتح النص الحالي للقانون ولا صفحة لوزارة العمل. ساعدنا في مطابقتهما مع القانون رقم 14 لسنة 2004 وتعديلاته اللاحقة.</li><li><strong>مكافأة نهاية الخدمة.</strong> يذكر الدليل الآن المبلغ من المادة 54 في نسخة 2006 تلك. فهل تغيرت هذه المادة منذ ذلك الحين؟ أرسل إلينا رابط النص الحالي من فضلك.</li><li><strong>الحد الأدنى الحالي للأجور.</strong> هل ما زال رقم 2021 صحيحًا في 2026؟</li><li><strong>أساسيات مطراش2.</strong> أين رابط التحميل الرسمي، وكيف تسجّل في التطبيق أو تفعّله؟ لم تفتح لنا صفحات مطراش2 على موقع وزارة الداخلية.</li><li><strong>شركات الصرافة المرخصة.</strong> أين ينشر مصرف قطر المركزي القائمة الحالية ليتأكد القارئ من الترخيص؟ أصبحت صفحات التسجيل القديمة في موقع المصرف تقود إلى صفحة خطأ.</li><li><strong>قانون الإيجار.</strong> القانون رقم 4 لسنة 2008 وتعديلاته: من يسجّل عقد الإيجار الجديد، وفي أي مهلة، وبأي تكلفة، وماذا يقول القانون عن مبلغ التأمين؟</li><li><strong>البطاقة الصحية والبطاقة الشخصية.</strong> تذكر تقارير إخبارية أن البطاقة الشخصية السارية حلت محل البطاقة الصحية المطبوعة للمقيمين في أبريل 2026. لم نجد ذلك في صفحات وزارة الصحة العامة أو مؤسسة حمد الطبية أو مؤسسة الرعاية الصحية الأولية.</li><li><strong>التأمين الصحي للمقيمين.</strong> الصفحات الرسمية التي قرأناها تتناول نظام الزوار فقط. فما الذي ينطبق على المقيمين، ومن يدفع؟</li></ul><h2 id="الوصول-والإقامة" tabindex="-1">الوصول والإقامة <a class="header-anchor" href="#الوصول-والإقامة" aria-label="Permalink to &quot;الوصول والإقامة&quot;">​</a></h2><ul><li>قوائم الدول المعفاة من التأشيرة، ومدة الإقامة المسموح بها لكل جنسية.</li><li>رسوم هيّا ومدد الإقامة والشروط لكل نوع من التأشيرات.</li><li>هل يمكن للزائر تمديد تأشيرة الوصول أو تأشيرة هيّا؟</li><li>ما يمكن توقعه في مطار حمد الدولي إضافة إلى جواز السفر والتذكرة والتأمين، بما في ذلك البوابات الإلكترونية والجمارك.</li><li>من يتقدم بطلب تأشيرة العمل، وهل ينطبق الفحصان الطبيان اللذان تذكرهما وزارة الداخلية معًا؟</li><li>خطوات ورسوم استبدال البطاقة الشخصية المفقودة أو التالفة، وقاعدة الإبلاغ عن الفقد.</li><li>من الذي ما زال يحتاج إلى إذن خروج، وكيف تعمل قواعد المغادرة اليوم؟</li><li>أين يجب إجراء الفحص الطبي للإقامة، وماذا يشمل؟</li></ul><h2 id="العائلة" tabindex="-1">العائلة <a class="header-anchor" href="#العائلة" aria-label="Permalink to &quot;العائلة&quot;">​</a></h2><ul><li>هل ما زال الفحص الطبي في الخارج مطلوبًا لإقامة العائلة؟ تختلف صفحتان لوزارة الداخلية في ذلك.</li><li>مبلغ الراتب المشترط لتوفير السكن في إقامة العائلة، إذ تختلف فيه صفحات وزارة الداخلية القديمة والحديثة، ويعرض الدليل الرقمين معًا.</li><li>المهلة المحددة لطلب إقامة طفل وُلد في قطر.</li><li>هل يمكن للأم العاملة أن تكفل أطفالها، أو للزوجة العاملة أن تكفل زوجها؟</li><li>قواعد تصديق شهادات الزواج والميلاد الصادرة في الخارج.</li></ul><h2 id="القيادة" tabindex="-1">القيادة <a class="header-anchor" href="#القيادة" aria-label="Permalink to &quot;القيادة&quot;">​</a></h2><ul><li>أهم قواعد المرور: حدود السرعة وحزام الأمان واستخدام الهاتف ومقاعد الأطفال ونظام النقاط.</li><li>مبالغ المخالفات.</li><li>الجنسيات التي يمكنها تحويل رخصة أجنبية دون دورة تدريبية.</li><li>هل يمكن للمقيم الذي يحمل بطاقة شخصية أن يواصل القيادة برخصة دولية؟</li><li>مدة صلاحية الرخصة لغير القطريين.</li><li>ما يجب فعله بعد حادث خطير.</li></ul><h2 id="المال-والسكن" tabindex="-1">المال والسكن <a class="header-anchor" href="#المال-والسكن" aria-label="Permalink to &quot;المال والسكن&quot;">​</a></h2><ul><li>هل يجب أن تشتكي إلى البنك قبل التوجه إلى مصرف قطر المركزي، وكم يستغرق رد المصرف؟</li><li>أرقام هواتف حماية المستهلك في مصرف قطر المركزي، إذ تذكر صفحتان للمصرف أرقامًا مختلفة.</li><li>قائمة حديثة بما تطلبه البنوك لفتح حساب، فالنص الرسمي الذي قرأناه يعود إلى 2013.</li><li>كيفية رفع دعوى أمام لجنة فض المنازعات الإيجارية.</li><li>مبلغ التأمين لحساب كهرماء، وكيفية إغلاق الحساب عند الانتقال.</li><li>تعرفة كهرماء بصيغة يمكن الاقتباس منها.</li><li>هل تفرض قطر ضريبة القيمة المضافة؟</li><li>إصدار من الرقم القياسي لأسعار المستهلك أحدث من يونيو 2026.</li></ul><h2 id="التنقل-والهاتف-والطوارئ" tabindex="-1">التنقل والهاتف والطوارئ <a class="header-anchor" href="#التنقل-والهاتف-والطوارئ" aria-label="Permalink to &quot;التنقل والهاتف والطوارئ&quot;">​</a></h2><ul><li>أجرة المترو والترام، وأسعار بطاقة السفر، وأين تُشترى أو تُشحن.</li><li>مواعيد تشغيل المترو والترام بالضبط.</li><li>أجرة حافلات كروة وبطاقاتها الذكية وقائمة خطوطها.</li><li>تفاصيل الألياف المنزلية من Ooredoo.</li><li>هل ما زالت مدد الشكاوى التي أعلنتها هيئة تنظيم الاتصالات في 2019 و2020 سارية؟</li><li>أرقام مستقلة للشرطة والإطفاء وخفر السواحل، إن وجدت.</li><li>أرقام الطوارئ الخاصة بتسرب الغاز والصرف الصحي والطرق.</li></ul><h2 id="الإجازات-والمدارس" tabindex="-1">الإجازات والمدارس <a class="header-anchor" href="#الإجازات-والمدارس" aria-label="Permalink to &quot;الإجازات والمدارس&quot;">​</a></h2><ul><li>القائمة الرسمية للإجازات العامة، وكيف يُعلن عن كل موعد.</li><li>قاعدة تحديد موعد اليوم الرياضي للدولة، وهل هو من الأيام التي يحددها صاحب العمل في القطاع الخاص؟</li><li>ساعات العمل في رمضان 2026 في القطاع الخاص وفي الجهات الحكومية.</li><li>نموذج شكاوى المدارس الخاصة ودليل التسجيل على موقع وزارة التربية والتعليم، إذ لم يفتحا لنا.</li></ul><h2 id="مواقع-لم-نستطع-قراءتها-آليًا" tabindex="-1">مواقع لم نستطع قراءتها آليًا <a class="header-anchor" href="#مواقع-لم-نستطع-قراءتها-آليًا" aria-label="Permalink to &quot;مواقع لم نستطع قراءتها آليًا&quot;">​</a></h2><p>افتح هذه المواقع في متصفح عادي من فضلك. بعضها يرفض الزوار الآليين، وبعضها لم يستجب من المكان الذي فحصنا منه في أكتوبر ونوفمبر 2026، وهذا لا يعني أنها معطلة عندك.</p><ul><li>طلبت فحصًا للروبوتات أو رفضت الطلب: hukoomi.gov.qa وgco.gov.qa وmof.gov.qa وalmeezan.qa وimo.gov.qa.</li><li>لم يتم الاتصال بها أو انقطع: mol.gov.qa وqr.com.qa وdiwan.gov.qa وcm.gov.qa وdohahamadairport.com.</li></ul>',20)])])}const m=i(o,[["render",t]]);export{g as __pageData,m as default};
